import React from "react";
import { useNavigate } from "react-router-dom";
import styled from "styled-components";

const LorryCard = ({ lorry }) => {
  const navigate = useNavigate();

  const handleClick = () => {
    if (lorry && lorry.registrationNumber) {
      navigate(`/dashboard/${lorry.registrationNumber}`);
    } else {
      console.error("Lorry data is incomplete.");
    }
  };

  if (!lorry) {
    return <Card>Loading...</Card>;
  }

  return (
    <Card onClick={handleClick}>
      <h3>{lorry.registrationNumber || "N/A"}</h3>
      <p>{lorry.model || "Model not available"}</p>
    </Card>
  );
};

export default LorryCard;

// Styled Components
const Card = styled.div`
  border: 1px solid #ddd;
  padding: 20px;
  text-align: center;
  width: 200px;
  cursor: pointer;
  border-radius: 10px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s ease;

  &:hover {
    transform: scale(1.05);
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
  }

  &:active {
    background-color: #f0f0f0;
  }

  h3 {
    margin: 0;
    font-size: 20px;
    font-weight: bold;
  }

  p {
    color: #777;
  }
`;
